/// Exposes the same account-scoped local save wherever layout actions appear.
class PortalLayoutSaveButton extends StatelessWidget {
  final String tooltip;
  const PortalLayoutSaveButton({super.key, required this.tooltip});

  @override
  Widget build(BuildContext context) {
    final workspace = PortalWorkspaceScope.maybeOf(context);
    return PrimeIconButton(
      tooltip: tooltip,
      onPressed: workspace?.preferences == null ? null : () => _operation(
        context,
        () async {
          await workspace!.save();
          return 'Layout saved on this device.';
        },
      ),
      icon: const PrimeIcon(Icons.save_outlined, size: 18),
    );
  }
}

/// The toolbar shortcut uses the same reversible fold setting as the editor.
class PrimeSidebarFoldButton extends StatelessWidget {
  final WorkspaceController controller;
  final Color foreground;
  const PrimeSidebarFoldButton({
    super.key,
    required this.controller,
    required this.foreground,
  });

  @override
  Widget build(BuildContext context) {
    final folded = controller.current.navigationWidth ==
        PrimeShellMetrics.foldedNavigationMarker;
    return Semantics(
      container: true,
      expanded: !folded,
      child: Center(
        child: DecoratedBox(
          decoration: PrimeShellMetrics.sidebarToggleDecoration(Theme.of(context)),
          child: PrimeIconButton(
          icon: PrimeIcon(
            LucideIcons.panelLeft,
            size: PrimeShellMetrics.sidebarIconExtent,
            color: foreground,
          ),
          tooltip: themeCenterOption(context, 'color.sidebar'),
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints.tightFor(
            width: PrimeShellMetrics.sidebarToggleSize,
            height: PrimeShellMetrics.sidebarToggleSize,
          ),
          onPressed: () => controller.patch({
            'navigationWidth': folded
                ? controller.expandedNavigationWidth
                : PrimeShellMetrics.foldedNavigationMarker,
          }),
          ),
        ),
      ),
    );
  }
}

